CREATE TABLE public.events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, event_date date, vehicle_types jsonb NOT NULL DEFAULT '[{"name":"Motor","tariff":3000}]'::jsonb, status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','archived')), created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.events TO anon; GRANT ALL ON public.events TO service_role; ALTER TABLE public.events ENABLE ROW LEVEL SECURITY; CREATE POLICY anon_full_events ON public.events FOR ALL TO anon USING (true) WITH CHECK (true); CREATE POLICY service_full_events ON public.events FOR ALL TO service_role USING (true) WITH CHECK (true); CREATE TABLE public.tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES public.events(id) ON DELETE CASCADE, code text NOT NULL UNIQUE, plate text NOT NULL, vehicle_type text NOT NULL, tariff numeric NOT NULL DEFAULT 0, payment_status text NOT NULL DEFAULT 'unpaid' CHECK (payment_status IN ('unpaid','prepaid','paid_at_exit')), entry_at timestamptz NOT NULL DEFAULT now(), exit_at timestamptz, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX tickets_event_idx ON public.tickets (event_id); CREATE INDEX tickets_plate_idx ON public.tickets (plate); CREATE INDEX tickets_exit_idx ON public.tickets (event_id, exit_at); GRANT SELECT, INSERT, UPDATE, DELETE ON public.tickets TO anon; GRANT ALL ON public.tickets TO service_role; ALTER TABLE public.tickets ENABLE ROW LEVEL SECURITY; CREATE POLICY anon_full_tickets ON public.tickets FOR ALL TO anon USING (true) WITH CHECK (true); CREATE POLICY service_full_tickets ON public.tickets FOR ALL TO service_role USING (true) WITH CHECK (true); ALTER PUBLICATION supabase_realtime ADD TABLE public.tickets; ALTER PUBLICATION supabase_realtime ADD TABLE public.events;